function normalizeEmotionForMaoxiang(emo) {
    emo = String(emo == null ? "" : emo).replace(/^\s+|\s+$/g, "").toLowerCase();
    if (!emo) return "";

    var alias = {
        "平静": "neutral", "中性": "neutral", "自然": "neutral", "默认": "neutral", "无": "neutral", "neutral": "neutral",
