function handleWenxinRequest(request, callback2, voiceId) {
    callback = callback2;
    audioChunks = [];
    audioLength = 0;
    isFinished = false;

    var speed = Math.round(((request.rate || 60) / 100) * 10);
    var pitch = Math.round(((request.pitch || 50) / 100) * 10);
