    'onLoadUI': function(ctx, linearLayout) {
        let customVoiceEditor = JTextInput(ctx, "自定义声音代号 (例如: 130048_4)");
        customVoiceEditor.setVisibility(View.GONE);
        linearLayout.addView(customVoiceEditor);
        ttsrv.setMargins(customVoiceEditor, 0, 8, 0, 0);

        customVoiceEditor.setOnTextChangedListener(function(text) {
            ttsrv.tts.data['customVoice'] = text;
        });

        let soundEffectSpinner = JSpinner(ctx, "音效模式 (Sound Effect)");
        linearLayout.addView(soundEffectSpinner);
        ttsrv.setMargins(soundEffectSpinner, 0, 4, 0, 0);

        let soundEffectItems = [
            Item("关闭 (Off)", "0"),
            Item("忽远忽近 (Fade)", "1"),
            Item("回声 (Echo)", "2"),
            Item("机器人 (Robot)", "3"),
            Item("合唱 (Chorus)", "4"),
            Item("水下 (Underwater)", "5"),
            Item("混响 (Reverb)", "6"),
            Item("阴阳怪气 (Weird)", "7")
        ];
        soundEffectSpinner.items = soundEffectItems;

        let currentSoundEffect = ttsrv.tts.data['soundEffect'];
        if (!currentSoundEffect) {
            currentSoundEffect = "0";
        }

        let selectedIndex = 0;
        for (let i = 0; i < soundEffectItems.length; i++) {
            if (soundEffectItems[i].value === currentSoundEffect) {
                selectedIndex = i;
                break;
            }
        }
        soundEffectSpinner.selectedPosition = selectedIndex;

        soundEffectSpinner.setOnItemSelected(function(spinner, pos, item) {
            ttsrv.tts.data['soundEffect'] = item.value;
        });

        let seekEmo = JSeekBar(ctx, "情感强度 (Emotion intensity)：");
        linearLayout.addView(seekEmo);
        ttsrv.setMargins(seekEmo, 0, 4, 0, -4);

        seekEmo.max = 40;

