function readinMp3FirstFrame(bytes, searchStart) {
    var mpeg1Bitrates = [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 0];
    var mpeg2Bitrates = [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160, 0];
    var sampleRates = [44100, 48000, 32000, 0];
    var limit = Math.min(bytes.length - 4, searchStart + 4096);
    for (var offset = searchStart; offset <= limit; offset++) {
        var b0 = readinUnsigned(bytes[offset]);
        var b1 = readinUnsigned(bytes[offset + 1]);
        var b2 = readinUnsigned(bytes[offset + 2]);
        var b3 = readinUnsigned(bytes[offset + 3]);
        if (b0 !== 255 || (b1 & 224) !== 224) continue;
        var version = (b1 >>> 3) & 3;
        var layer = (b1 >>> 1) & 3;
        var bitrateIndex = (b2 >>> 4) & 15;
        var sampleRateIndex = (b2 >>> 2) & 3;
        if (version === 1 || layer !== 1 || bitrateIndex === 0 || bitrateIndex === 15 || sampleRateIndex === 3) continue;
        var bitrate = (version === 3 ? mpeg1Bitrates : mpeg2Bitrates)[bitrateIndex];
        var sampleRate = sampleRates[sampleRateIndex];
        if (version === 2) sampleRate = sampleRate / 2;
        else if (version === 0) sampleRate = sampleRate / 4;
        var padding = (b2 >>> 1) & 1;
        var frameLength = Math.floor((version === 3 ? 144000 : 72000) * bitrate / sampleRate) + padding;
