function readinRequestToken(output, input, voice) {
    var now = new Date().getTime();
    var logId = "android1.7.3_" + now + "_" + READIN_USER_ID + "_" + String(ttsrv.randomUUID()).replace(/-/g, "");
    var param = JSON.stringify({
        appId: READIN_APP_ID,
        terminalType: 0,
        sdkType: 6,
        sdkVersion: "1.7.3",
        engineName: voice,
        checkType: 2,
        endsil: 8,
