        ttsParam: param,
        ts: Number(now),
        secretKey: readinMd5(READIN_APP_KEY + param + now)
    });
    readinWriteFrame(output, 30, readinUtf8(body));
    var frame = readinReadFrame(input);
    if (frame.type === 42) throw new Error("本悦读令牌失败：" + readinErrorBody(frame.body));
    if (frame.type !== 40 || frame.body.length < 1 || readinUnsigned(frame.body[0]) !== 1) {
        throw new Error("本悦读令牌响应无效（类型 " + frame.type + "）");
