function readinRequestAudio(output, input, text, voice, speed, volume, pitch, collector) {
    var body = JSON.stringify({
        sum: 1,
        order: 1,
        samplingRate: 2,
        audioType: 1,
        text: text,
        enableEmotion: readinEmotionEnabled() ? 1 : 0,
        lan: "zh-CN",
        ttsParam: JSON.stringify({ sex: 0, vol: volume, speed: speed, pitch: pitch }),
        options: "{}"
    });
    readinWriteFrame(output, 31, readinUtf8(body));
    var audioBytes = 0;
    var expected = 0;
    var received = 0;
    var coverageKnown = false;
    var coveredTextEnd = 0;
    while (true) {
        var frame = readinReadFrame(input);
        if (frame.type === 42) throw new Error("本悦读合成失败：" + readinErrorBody(frame.body));
        if (frame.type !== 41) continue;
        var packet = JSON.parse(readinByteString(frame.body));
        expected = Math.max(expected, Number(packet.sum || 0));
        received = Math.max(received, Number(packet.order || 0));
        if (typeof packet.textEnd !== "undefined" && packet.textEnd !== null) {
            coverageKnown = true;
            coveredTextEnd = Math.max(coveredTextEnd, Number(packet.textEnd || 0));
        }
        if (packet.data) {
            var chunk = readinDecodeBase64(packet.data);
            if (chunk && chunk.length > 0) {
                collector.push(chunk);
                audioBytes += chunk.length;
            }
        }
        if (expected > 0 && received >= expected) break;
    }
    if (audioBytes <= 0) throw new Error("本悦读没有返回音频");
    var uncoveredTail = coverageKnown && coveredTextEnd < text.length
        ? text.substring(coveredTextEnd).replace(/\s/g, "")
        : "";
    if (uncoveredTail.length > 0) {
        throw new Error("本悦读仅合成到第 " + coveredTextEnd + "/" + text.length + " 字，已拒绝写入残缺缓存");
    }
    return audioBytes;
}

function readinFetchSegment(text, voice, rate, volume, pitch) {
    var lastError = null;
    for (var hostIndex = 0; hostIndex < READIN_HOSTS.length; hostIndex++) {
        var socket = null;
        try {
            try {
                socket = readinRegisterSocket(readinConnectSocket(READIN_HOSTS[hostIndex]));
            } catch (socketError) {
                throw new Error("阶段=TCP连接；" + String(socketError));
            }
            socket.setSoTimeout(READIN_SOCKET_TIMEOUT_MS);
            socket.setTcpNoDelay(true);
            var output = socket.getOutputStream();
            var input = socket.getInputStream();
            try {
                readinRequestToken(output, input, voice);
            } catch (tokenError) {
                throw new Error("阶段=令牌；" + String(tokenError));
            }
            var chunks = [];
            var bytes;
            try {
                bytes = readinRequestAudio(
                    output,
                    input,
                    text,
                    voice,
                    readinMapSpeed(rate),
                    readinMapVolume(volume),
                    readinMapPitch(pitch),
                    chunks
                );
            } catch (audioError) {
                throw new Error("阶段=音频；" + String(audioError));
            }
            return { chunks: chunks, bytes: bytes };
        } catch (error) {
            lastError = error;
        } finally {
            if (socket !== null) {
                readinUnregisterSocket(socket);
                try { socket.close(); } catch (ignore) {}
            }
        }
    }
    throw new Error("本悦读线路连接失败：" + String(lastError || "未知错误"));
}

function readinSynthesize(text, voice, rate, volume, pitch, callback) {
    var selectedVoice = String(voice || "").trim() || READIN_DEFAULT_VOICE;
    var cleanText = readinCleanText(text);
    if (!cleanText.trim()) throw new Error("试听文本为空");
    var segments = readinSplitText(cleanText);
    var encodedChunks = [];
    for (var segmentIndex = 0; segmentIndex < segments.length; segmentIndex++) {
        var result;
        try {
            result = readinFetchSegment(
                segments[segmentIndex],
                selectedVoice,
                rate,
                volume,
                pitch
            );
        } catch (segmentError) {
            throw new Error(
                "长文本第 " + (segmentIndex + 1) + "/" + segments.length + " 段失败：" + String(segmentError)
            );
        }
        for (var chunkIndex = 0; chunkIndex < result.chunks.length; chunkIndex++) {
            encodedChunks.push(result.chunks[chunkIndex]);
        }
    }
    if (encodedChunks.length === 0) throw new Error("本悦读没有返回音频");
    var mergeIndependentMp3Files = encodedChunks.length > 1;
    var writtenBytes = 0;
    for (var encodedIndex = 0; encodedIndex < encodedChunks.length; encodedIndex++) {
        var outputChunk = mergeIndependentMp3Files
            ? readinMp3AudioPayload(encodedChunks[encodedIndex])
            : encodedChunks[encodedIndex];
        if (!outputChunk || outputChunk.length <= 0) throw new Error("本悦读音频帧合并结果为空");
        callback.write(outputChunk);
        writtenBytes += outputChunk.length;
    }
    if (writtenBytes <= 0) throw new Error("本悦读没有返回音频");
    return writtenBytes;
}

