    var savedAt = 0;
    var snapshot;
    try {
        var cachedText = String(ttsrv.readTxtFile(READIN_CACHE_FILE) || "");
        if (cachedText) {
            snapshot = JSON.parse(cachedText);
            if (snapshot.version !== 1) throw new Error("目录缓存版本异常");
            var cached = readinNormalizePublicVoices(snapshot.voices);
            READIN_VOICES = readinMergeCatalog(READIN_VOICES, cached);
            savedAt = Number(snapshot.savedAt || 0);
            READIN_CATALOG_SOURCE = "缓存目录";
        }
    } catch (cacheError) {
        READIN_CATALOG_ERROR = "缓存不可用，使用内置目录";
    }
    if (savedAt > 0 && savedAt <= now && now - savedAt < READIN_CACHE_TTL_MS) return;
    try {
        var response = ttsrv.httpGet(READIN_CATALOG_URL, {"x-app-name": "readifyai", "x-lang": "zh-CN"}, 10000);
        var packet = JSON.parse(String(response.body().string()));
        if (packet.code !== 0) throw new Error("官方目录返回业务错误");
        var fresh = readinNormalizePublicVoices(packet.data);
