        throw new Error("请先在插件列表点登录，登录自己的悦读账号后点完成登录，再打开我的克隆");
    }
    var now = new Date().getTime();
    if (!force && READIN_ACCOUNT_LOADED_AT > 0 && now >= READIN_ACCOUNT_LOADED_AT && now - READIN_ACCOUNT_LOADED_AT < READIN_ACCOUNT_TTL_MS) return READIN_ACCOUNT_VOICES.slice(0);
    var response;
    try {
        response = ttsrv.httpGet(READIN_CLONE_LIST_URL, {
            "x-token": token,
            "x-app-name": "readifyai",
            "x-lang": "zh-CN",
            "Accept": "application/json",
            "Origin": "https://app.readifyai.com",
            "Referer": "https://app.readifyai.com/library/voices"
        }, 15000);
    } catch (networkError) {
        // Do not leak host exception text: it can contain request headers or account data.
        readinResetAccountCatalog(token);
        throw new Error("悦读账号音色读取失败，请检查网络后重新打开我的克隆");
    }
    var status = Number(response.code());
    if (status === 401 || status === 403) {
        readinResetAccountCatalog(token);
        throw new Error("悦读登录已失效，请在插件列表重新登录自己的账号");
    }
    if (status < 200 || status >= 300) {
        readinResetAccountCatalog(token);
        throw new Error("悦读账号音色服务暂不可用，请稍后重新打开我的克隆");
    }
    var packet;
    try { packet = JSON.parse(String(response.body().string())); }
    catch (decodeError) {
        readinResetAccountCatalog(token);
        throw new Error("悦读账号音色响应格式异常，请重试");
    }
    if (!packet || packet.code !== 0) {
        readinResetAccountCatalog(token);
        throw new Error("悦读账号会话未通过，请重新登录；账号音色未加载");
    }
    var voices;
    try { voices = readinNormalizeCloneVoices(packet.data); }
    catch (schemaError) {
        readinResetAccountCatalog(token);
        throw new Error("悦读账号音色列表格式异常，请重试");
    }
    READIN_ACCOUNT_VOICES = voices;
    READIN_ACCOUNT_LOADED_AT = now;
    return voices.slice(0);
}

function readinVoiceOptions(voices) {
    var out = {};
    for (var i = 0; i < voices.length; i++) {
