// Account session repair: use the official user refresh-token flow, not a captured short-lived token.
var READIN_SESSION_KEY = "readifyAccountSession";
var READIN_REFRESH_URL = "https://app.readifyai.com/api/users/tokens";
var READIN_SESSION_SCOPE = "";

function readinAccountSession() {
    var raw = "";
    try { raw = readinMapValue(ttsrv.tts.userVars, READIN_SESSION_KEY); } catch (ignored) {}
    if (!raw) {
        try { raw = readinMapValue(ttsrv.userVars, READIN_SESSION_KEY); } catch (ignored2) {}
    }
    if (!raw) throw new Error("请在本悦读v12插件点登录，确认自己的账号后点完成登录，以保存账号会话；旧v11登录值不用于本版续期");
    var session;
    try { session = JSON.parse(raw); }
    catch (decodeError) { throw new Error("悦读账号会话格式异常，请在v12重新完成网页登录"); }
    var refresh = session && session.refreshToken;
    if (typeof refresh !== "string" || !refresh || refresh.length > 65536 || /[\r\n]/.test(refresh)) {
        throw new Error("悦读网页尚未保存账号续期信息，请确认已登录账号并打开我的音色，再点完成登录");
    }
    return session;
}

function readinAccountHeaders(session) {
    return {
        "x-app-name": "readifyai", "x-lang": "zh-CN",
        "x-device-id": String(session.deviceId || session.visitorUuid || READIN_USER_ID),
        "x-user-agent": "web", "x-time-zone": "Asia/Shanghai", "x-client-region": "CN",
        "x-os": "Android", "Accept": "application/json",
        "Content-Type": "application/json;charset=UTF-8",
        "Origin": "https://app.readifyai.com", "Referer": "https://app.readifyai.com/library/voices"
    };
}

function readinSafeBusinessCode(packet) {
    var code = packet && packet.code;
    return typeof code === "number" || (typeof code === "string" && /^-?\d{1,12}$/.test(code)) ? String(code) : "非标准";
}

function readinAccountPacket(response, stage) {
    var status = Number(response.code());
    if (status < 200 || status >= 300) throw new Error("悦读" + stage + "失败：HTTP " + status + "；请检查网络或重新完成登录");
    var packet;
    try { packet = JSON.parse(String(response.body().string())); }
    catch (decodeError) { throw new Error("悦读" + stage + "响应不是有效JSON，请稍后重试"); }
    // The official client accepts both numeric 0 and string "0".
    if (!packet || !(packet.code === 0 || packet.code === "0")) {
        throw new Error("悦读" + stage + "失败：业务码 " + readinSafeBusinessCode(packet) + "；账号未通过服务端验证");
    }
    return packet;
}

function readinRefreshAccountToken(session) {
    var headers = readinAccountHeaders(session);
    headers["x-refresh-token"] = session.refreshToken;
    var response;
    try { response = ttsrv.httpPost(READIN_REFRESH_URL, "", headers, 15000); }
    catch (networkError) { throw new Error("悦读账号续期请求失败，请检查网络；未读取旧私人列表"); }
    var packet = readinAccountPacket(response, "账号续期");
    var token = packet.data && packet.data.userToken;
    if (typeof token !== "string" || !token || token.length > 65536 || /[\r\n]/.test(token)) {
        throw new Error("悦读账号续期未返回有效userToken，请重新完成网页登录");
    }
    return token;
}

function readinTraceAccountCounts(total, available) {
    try {
        if (typeof console !== "undefined" && typeof console.info === "function") {
            console.info("Readify账号目录：服务器条目=" + total + "，可用普通话克隆=" + available);
        }
    } catch (ignored) {}
}

// Replace the v11 loader; its public catalog and original TCP synthesis are unchanged.
readinLoadAccountVoices = function(force) {
    var session;
    try { session = readinAccountSession(); }
    catch (sessionError) { readinResetAccountCatalog(""); READIN_SESSION_SCOPE = ""; throw sessionError; }
    var scope = String(session.userId || session.id || "") + ":" + String(ttsrv.md5Encode(session.refreshToken));
    if (scope !== READIN_SESSION_SCOPE) {
        readinResetAccountCatalog("");
        READIN_SESSION_SCOPE = scope;
    }
    var now = new Date().getTime();
    if (!force && READIN_ACCOUNT_LOADED_AT > 0 && now >= READIN_ACCOUNT_LOADED_AT && now - READIN_ACCOUNT_LOADED_AT < READIN_ACCOUNT_TTL_MS) return READIN_ACCOUNT_VOICES.slice(0);
    // Never retain an earlier list when either refresh or list verification fails.
    readinResetAccountCatalog("");
    try {
        var token = readinRefreshAccountToken(session);
        var headers = readinAccountHeaders(session);
        headers["x-token"] = token;
        var response;
        try { response = ttsrv.httpGet(READIN_CLONE_LIST_URL, headers, 15000); }
        catch (networkError) { throw new Error("悦读账号音色请求失败，请检查网络后重新打开我的克隆"); }
        var packet = readinAccountPacket(response, "账号音色查询");
        var voices;
        try { voices = readinNormalizeCloneVoices(packet.data); }
        catch (schemaError) { throw new Error("悦读账号音色列表结构异常；请保留本次错误日志"); }
        readinTraceAccountCounts(packet.data.length, voices.length);
        READIN_ACCOUNT_VOICES = voices;
        READIN_ACCOUNT_LOADED_AT = now;
        return voices.slice(0);
    } catch (accountError) {
        readinResetAccountCatalog("");
        throw accountError;
    }
};

