function extractEmotionBridgeInfo(text) {
    var s = String(text == null ? "" : text);
    var m = s.match(/\[\[(?:emo|emotion)\s*[:=]\s*([^\]|,:：，]+)\s*(?:[\]|,:：，]\s*([0-9.]+))?\s*\]\]/i);
