        "愤怒": "angry", "生气": "angry", "恼怒": "angry", "怒": "angry", "angry": "angry",
        "害怕": "fear", "恐惧": "fear", "惊恐": "fear", "害怕恐惧": "fear", "fear": "fear",
        "惊讶": "surprised", "吃惊": "surprised", "疑惑": "surprised", "surprised": "surprised",
