/* __JREAD_VOICE_MIX_V1__ */
/* __JREAD_VOICE_MIX_V2__
 * 可选三音色混音：未选附加音色时保持原免登录单音色；只选第二音色时为双混音；
 * 同时选择第二、第三音色时为三混音。主音色和第二音色设置比例，第三音色自动使用余量。
 */
function doubaoMixTrim(value) {
    return String(value == null ? "" : value).trim();
}

function doubaoMixRead(source, key) {
    if (!source) return "";
    try {
        var value = source[key];
        return value == null ? "" : doubaoMixTrim(value);
    } catch (ignored) {
        return "";
    }
}

function doubaoMixSetting(request, key) {
    var value = "";
    try { value = doubaoMixRead(request && request.data, key); if (value) return value; } catch (e0) {}
    try { value = doubaoMixRead(ttsrv.tts && ttsrv.tts.data, key); if (value) return value; } catch (e1) {}
    return "";
}

function doubaoMixSecondVoice(request) {
    return doubaoMixSetting(request, "mixSecondVoice");
}

function doubaoMixThirdVoice(request) {
    return doubaoMixSetting(request, "mixThirdVoice");
}

function doubaoMixIsEnabled(request) {
    return doubaoMixSecondVoice(request) !== "" || doubaoMixThirdVoice(request) !== "";
}

function doubaoMixIsEligibleVoice(voiceId) {
    // [FIX-2026-10-16 v5] 实测豆包内所有音色均可参与混音（uranus/mars/wvae/ICL/
    // BV*_streaming 等无一例外）。原白名单（排除 uranus/dit_/saturn_/create_voice_）
    // 是误判，会把用户主力音色的混音静默降级成单音色。这里只校验非空。
    var id = doubaoMixTrim(voiceId);
    return id !== "";
}

function doubaoMixNumber(value, fallback) {
    var numberValue = parseFloat(doubaoMixTrim(value));
    return isNaN(numberValue) ? fallback : numberValue;
}

function doubaoMixClamp(value, minimum, maximum) {
    return Math.max(minimum, Math.min(maximum, value));
}

function doubaoMixPercentages(request, hasThird) {
    // [FIX-2026-10-16 v7] 豆包 App 内混音是“自由比例滑块”，任意 0~100 可调。
    // 原实现把主音色锁 10~80、第二音色锁 >=10，与滑块冲突（用户调不动）。
    // 现在：三路各自读 0~100，不再设下限；总和自动归一化到 100%。
    var p = doubaoMixClamp(doubaoMixNumber(doubaoMixSetting(request, "mixPrimaryPercent"), hasThird ? 40 : 70), 0, 100);
    var s = doubaoMixClamp(doubaoMixNumber(doubaoMixSetting(request, "mixSecondPercent"), hasThird ? 35 : 30), 0, 100);
    var t = 0;
    if (hasThird) {
        var rawThird = doubaoMixSetting(request, "mixThirdPercent");
        if (rawThird === "" || rawThird === null || typeof rawThird === "undefined") {
            t = Math.max(0, 100 - p - s);      // 未给第三路则取余量
        } else {
            t = doubaoMixClamp(doubaoMixNumber(rawThird, 25), 0, 100);
        }
    }
    var sum = p + s + t;
    if (sum <= 0) { p = 100; s = 0; t = 0; sum = 100; }
    return {primary: p / sum * 100, second: s / sum * 100, third: (hasThird ? t / sum * 100 : 0)};
}

