// ==================== 猫箱请求处理（集成情绪桥接） ====================
function handleMaoxiangRequest(request, callback2, voiceId) {
    var speechRateFactor = 1.0;
    var pitchValue = 0;
    var rate = Number(request.rate) || 50;
    var pitch = Number(request.pitch) || 50;
    speechRateFactor = rate / 50;
    speechRateFactor = Math.max(0.5, Math.min(2.0, speechRateFactor));
    pitchValue = Math.round((pitch - 50) / 10);
    pitchValue = Math.max(-5, Math.min(5, pitchValue));

    var loudnessRate = 0;
    var volume = Number(request.volume) || 50;
    loudnessRate = volume - 50;
    loudnessRate = Math.max(-50, Math.min(100, loudnessRate));

    callback = callback2;
    audioChunks = [];
    audioLength = 0;
    isFinished = false;

    var audioFormat = String(ttsrv.tts.data["audioFormat"] || "mp3");
    var sampleRate = parseInt(ttsrv.tts.data["sampleRate"]) || CONFIG.sampleRate;
    var contextTexts = String(ttsrv.tts.data["contextTexts"] || "");
    var specialVoice = isSpecialVoice(voiceId);

    // ========== 情绪桥接解析 ==========
    var emotionInfo = resolvePostModuleEmotion(request, String(request.text || ""));

    // 第二音色为空时保持单音色；第三音色为空时为双混音；两个附加音色都选择时为三混音。
    var mixSecondVoice = doubaoMixSecondVoice(request);
    var mixThirdVoice = doubaoMixThirdVoice(request);
    var mixEnabled = mixSecondVoice !== "" || mixThirdVoice !== "";
    if (mixThirdVoice && !mixSecondVoice) {
        callback2.error("请先选择第二音色，再选择第三音色");
        try { callback2.close(); } catch(e) {}
        isRequesting = false;
        return;
    }
    var mixThreeEnabled = mixSecondVoice !== "" && mixThirdVoice !== "";
    var mixPercentages = doubaoMixPercentages(request, mixThreeEnabled);
    if (mixEnabled) {
        mixSecondVoice = resolveAvailableMaoxiangVoiceId(mixSecondVoice);
        if (mixThreeEnabled) mixThirdVoice = resolveAvailableMaoxiangVoiceId(mixThirdVoice);
        if (voiceId === mixSecondVoice || voiceId === mixThirdVoice || (mixThirdVoice && mixSecondVoice === mixThirdVoice)) {
            callback2.error("主音色、第二音色和第三音色必须互不相同");
            try { callback2.close(); } catch(e) {}
            isRequesting = false;
            return;
        }
        if (!doubaoMixIsEligibleVoice(voiceId) ||
            !doubaoMixIsEligibleVoice(mixSecondVoice) ||
            (mixThreeEnabled && !doubaoMixIsEligibleVoice(mixThirdVoice))) {
            // [补丁1] 墨听D包 AudioCallback 收到 error 会抛异常，整段合成失败 => 无声。
            // 改为自动清空附加音色，降级为单音色继续合成。
            console.log("[混音降级] 音色组合不支持免登录混音，自动回退单音色: " + voiceId);
            mixSecondVoice = "";
            mixThirdVoice = "";
            mixThreeEnabled = false;
            mixEnabled = false;
        }
        audioFormat = "mp3";
    }

var adjustedTimeout = CONFIG.firstChunkTimeoutMs;
    if (speechRateFactor > 1.2) {
        adjustedTimeout = Math.min(8000, CONFIG.firstChunkTimeoutMs * 1.5);
    } else if (speechRateFactor < 0.8) {
        adjustedTimeout = Math.min(6000, CONFIG.firstChunkTimeoutMs * 1.2);
    }

    // ========== 插件内置AI情绪分析已移除 ==========
    // 只接收朗读规则/后置情绪模块传入的 emotion，不再自行请求模型分析情绪，
    // 避免与朗读规则情绪判断打架，也避免每段额外网络请求造成卡顿。
    var voiceList = voiceListCache || downloadVoiceList();
    var isPro = false;
    var voiceEmotions = [];
    if (voiceList) {
        for (var i = 0; i < voiceList.length; i++) {
            if (voiceList[i].voice_id === voiceId) {
                isPro = voiceList[i].is_pro === true;
                voiceEmotions = voiceList[i].emotions || [];
                break;
            }
        }
    }
    var isMultiEmotion = (voiceEmotions.length > 0);
    var isAdvanced = isPro || specialVoice;

    var finalEmotion = emotionInfo.emotion;
    var finalScale = emotionInfo.scale;
    var finalPrompt = emotionInfo.prompt;

    req = {
        text: emotionInfo.text,
        voice: voiceId,
        speechRateFactor: speechRateFactor,
        pitchValue: pitchValue,
        loudnessRate: loudnessRate,
        format: audioFormat,
        sampleRate: sampleRate,
        contextTexts: contextTexts,
        engineType: "maoxiang",
        isSpecialVoice: specialVoice,
        adjustedTimeout: adjustedTimeout,
        emotion: finalEmotion,
        emotionScale: finalScale,
        emotionPrompt: finalPrompt,
        isAdvanced: isAdvanced,
        mixEnabled: mixEnabled,
        mixSecondVoice: mixSecondVoice,
        mixThirdVoice: mixThirdVoice,
        mixPrimaryPercent: mixPercentages.primary,
        mixSecondPercent: mixPercentages.second,
        mixThirdPercent: mixPercentages.third
    };

    var inputTaskId = String(request.task_id || "").trim();
    if (inputTaskId) {
        currentTaskId = inputTaskId;
    }

    if (ws !== null) {
        try { ws.cancel(); } catch(e) {}
        ws = null;
        isWsReady = false;
    }
    // [v9] 新一轮请求：重置零音频重试状态
    maoxiangEmptyRetry = 0;
    maoxiangRetryPending = false;
    maoxiangGen++;
    connectMaoxiangWebSocket();
    lastVoiceId = voiceId;
}

function connectMaoxiangWebSocket() {
    var myGen = maoxiangGen;   // [v9] 绑定本次连接代次
    try {
        var wsUrl = buildMaoxiangWsUrl();
        ws = new Websocket(wsUrl, {});
    } catch(e) {
        isRequesting = false;
        try { callback.error("WebSocket连接失败: " + e.message); } catch(e2) {}
        try { callback.close(); } catch(e2) {}
        return;
    }

    ws.on('open', function() {
        isWsReady = true;
        wsConnectTime = Date.now();
        sendMaoxiangStartTask();
        startMaoxiangTimeoutCheck();
    });

    ws.on('close', function(code) {
        if (myGen !== maoxiangGen) return;   // [v9] 旧连接的迟到回调，丢弃
        ws = null;
        isWsReady = false;
        isRequesting = false;
        flushMaoxiangAudio("Close:" + code);
    });

    ws.on('error', function(err) {
        ws = null;
        isWsReady = false;
        isRequesting = false;
        try { callback.error("WebSocket错误: " + err); } catch(e) {}
        try { callback.close(); } catch(e) {}
    });

    ws.on('text', function(msg) {
        try {
            var data = JSON.parse(msg);
            if (data.type === 3 && data.buffer) {
                var decoded = android.util.Base64.decode(data.buffer, 0);
                if (decoded && decoded.length > 0) {
                    if (audioChunks.length === 0 && timeoutHandler !== null) {
                        timeoutHandler.interrupt();
                        timeoutHandler = null;
                    }
                    audioChunks.push(decoded);
                    audioLength += decoded.length;
                }
            } else {
                handleMaoxiangTextMessage(msg);
            }
        } catch(e) {
            handleMaoxiangTextMessage(msg);
        }
    });

    ws.on('binary', function(buf) {
        handleMaoxiangBinaryData(buf);
    });
}

function sendMaoxiangStartTask() {
    try {
        var payloadObj;

        var emotionPromptText = "";
        if (req.emotion && req.emotion !== "") {
            // v14：情绪提示词不再只限 Vivi/高级音色；若当前音色没有原生 emotion 参数，就转为 context_texts。
            emotionPromptText = buildEmotionContextPrompt(req.emotion, req.emotionScale, req.emotionPrompt);
        }

        if (req.isSpecialVoice) {
            payloadObj = {
                audio_config: {
                    format: req.format,
                    sample_rate: req.sampleRate,
                    loudness_rate: req.loudnessRate
                },
                extra: {
                    post_process: {
                        pitch: req.pitchValue,
                        speech_rate: req.speechRateFactor
                    }
                },
                speaker: req.voice
            };

            if (req.contextTexts && req.contextTexts.trim()) {
                var parseResult = parseContextRules(req.contextTexts);
                var prompt = getContextPrompt(req.text, parseResult);
                if (prompt) {
                    appendPayloadContextText(payloadObj, prompt);
                }
            }

            if (emotionPromptText) {
                appendPayloadContextText(payloadObj, emotionPromptText);
            }
        } else {
            payloadObj = {
                audio_config: {
                    format: req.format,
                    sample_rate: req.sampleRate,
                    loudness_rate: req.loudnessRate
                },
                extra: {
                    post_process: {
                        pitch: req.pitchValue,
                        speech_rate: req.speechRateFactor
                    },
                    max_length_to_filter_parenthesis: 0
                },
                speaker: req.voice
            };

            if (req.contextTexts && req.contextTexts.trim()) {
                // v14：所有火山/猫剪可用音色都允许走提示词；多行“正则##提示词”也会按当前文本匹配。
                var parseResult2 = parseContextRules(req.contextTexts);
                var prompt2 = getContextPrompt(req.text, parseResult2);
                if (prompt2) {
                    appendPayloadContextText(payloadObj, prompt2);
                } else if (!parseResult2 || parseResult2.type === 'direct') {
                    appendPayloadContextText(payloadObj, req.contextTexts.trim());
                }
            }

            if (req.emotion && req.emotion !== "") {
                var supportedEmotion = getSupportedEmotionForVoice(req.voice, req.emotion);
                if (supportedEmotion) {
                    payloadObj.audio_config.emotion = supportedEmotion;
                    payloadObj.audio_config.emotion_scale = Number(req.emotionScale);
                } else {
                    console.log("[情绪] 音色不支持原生emotion参数，改用context_texts: " + req.emotion);
                    if (emotionPromptText) appendPayloadContextText(payloadObj, emotionPromptText);
                }
            }
        }

        if (req.mixEnabled) {
            var hasThirdVoice = String(req.mixThirdVoice || "") !== "";
            // [FIX-2026-10-16 v7] req.mix*Percent 已在 handleMaoxiangRequest 里由
            // doubaoMixPercentages 算好（自由比例 + 归一化）。这里直接取用，
            // 不再二次调用（req 上没有 .data 层，二次调用会读不到而落到默认值）。
            var primaryPercent = Math.round(Number(req.mixPrimaryPercent) || 0);
            var secondPercent = Math.round(Number(req.mixSecondPercent) || 0);
            var thirdPercent = hasThirdVoice ? Math.round(Number(req.mixThirdPercent) || 0) : 0;
            var mixSpeakers = [
                { source_speaker: req.voice, mix_factor: primaryPercent / 100 },
                { source_speaker: req.mixSecondVoice, mix_factor: secondPercent / 100 }
            ];
            if (hasThirdVoice) {
                mixSpeakers.push({ source_speaker: req.mixThirdVoice, mix_factor: thirdPercent / 100 });
            }
            // [FIX-v8 2026-10-17] 实测结论（对中转服务端冒烟测试，F0中位数单调）：
            //   纯男 115/164Hz  →  mix90%男/10%女 148/151Hz  →  50/50 197/212Hz
            //   →  mix10%男/90%女 261/279Hz  →  纯女 234/255Hz
            // 正确协议：speaker="custom_mix_bigtts" + mix_speaker.speakers=[{source_speaker,mix_factor}]
            // mix_factor 为 0~1 浮点。此前把 speaker 改为主音色ID是误判（v5 的误操作），
            // 会令 mix_factor 被完全忽略 —— 这正是"调比例没变化"的根因。
            payloadObj.speaker = "custom_mix_bigtts";
            payloadObj.mix_speaker = {speakers: mixSpeakers};
            // 混音使用提示词桥接情绪，避免把只属于主音色的原生 emotion 参数误套到合成音色。
            if (payloadObj.audio_config) {
                delete payloadObj.audio_config.emotion;
                delete payloadObj.audio_config.emotion_scale;
            }
            if (emotionPromptText) appendPayloadContextText(payloadObj, emotionPromptText);
        }


        var msg = {
            appkey: CONFIG.appkey,
            event: "StartTask",
            namespace: "BidirectionalTTS",
            payload: JSON.stringify(payloadObj)
        };

        if (currentTaskId) {
            msg.task_id = currentTaskId;
        }

        ws.send(JSON.stringify(msg));
    } catch(e) {
        var savedCallback = callback;
        try { savedCallback.error("发送StartTask失败: " + e.message); } catch(e2) {}
        try { savedCallback.close(); } catch(e2) {}
    }
}

function appendPayloadContextText(payloadObj, text) {
    text = String(text || "").replace(/^\s+|\s+$/g, "");
    if (!text) return;
    if (!payloadObj.context_texts) payloadObj.context_texts = [];
    payloadObj.context_texts.push(text);
}

