        volume: parseFloat(req.volume),
        format: "pcm",
        status: 1,
        sample_rate: 24000,
        extra_params: {chat_req_id: chatReqId}
    };

    var msg2 = {
        reqid: req.reqid,
        text: "",
        model: "QUARK_VOICE",
        vcn: req.voice,
        type: "stream",
