(function() {
    if (typeof PluginJS === "undefined" || typeof PluginJS.getAudioV2 !== "function") return;
    var __jreadFiveLaneOriginalGetAudioV2 = PluginJS.getAudioV2;
    var __jreadFiveLaneProviderKey = "maoxiang-shared";

    function __jreadFiveLaneHash(request) {
        request = request || {};
        var seed = __jreadFiveLaneProviderKey + "|" + String(request.voice || "") + "|" + String(request.text || "");
        var hash = 0;
        for (var i = 0; i < seed.length; i++) {
            hash = ((hash * 31) + seed.charCodeAt(i)) & 2147483647;
        }
        return hash;
    }

    function __jreadFiveLaneSleep(delayMs) {
        delayMs = Math.max(0, Math.min(1000, Number(delayMs) || 0));
        if (delayMs <= 0) return;
        try { java.lang.Thread.sleep(Math.floor(delayMs)); } catch (ignored) {}
    }

    function __jreadFiveLanePace(request) {
        var hash = __jreadFiveLaneHash(request);
        var fallbackDelay = 60 + (hash % 180);
        var randomAccessFile = null;
        var channel = null;
        var fileLock = null;
        try {
            var temporaryDirectory = String(java.lang.System.getProperty("java.io.tmpdir") || "");
            if (!temporaryDirectory) throw new Error("java.io.tmpdir unavailable");
            var paceFile = new java.io.File(
                temporaryDirectory,
                "jread_tts_5lane_" + __jreadFiveLaneProviderKey + ".pace"
            );
            randomAccessFile = new java.io.RandomAccessFile(paceFile, "rw");
            channel = randomAccessFile.getChannel();
            var lockDeadline = Date.now() + 1500;
            while (fileLock === null && Date.now() < lockDeadline) {
                try { fileLock = channel.tryLock(); } catch (lockBusy) {}
                if (fileLock === null) __jreadFiveLaneSleep(18 + (hash % 17));
            }
            if (fileLock === null) {
                __jreadFiveLaneSleep(fallbackDelay);
                return;
            }

            var lastStartAt = 0;
            if (randomAccessFile.length() > 0) {
                randomAccessFile.seek(0);
                lastStartAt = parseInt(String(randomAccessFile.readLine() || "0"), 10) || 0;
            }
            var minimumGapMs = 130 + (hash % 71);
            var waitMs = lastStartAt > 0 ? (lastStartAt + minimumGapMs - Date.now()) : 0;
            __jreadFiveLaneSleep(waitMs);
            randomAccessFile.setLength(0);
            randomAccessFile.seek(0);
            randomAccessFile.writeBytes(String(Date.now()));
        } catch (paceError) {
            __jreadFiveLaneSleep(fallbackDelay);
        } finally {
            if (fileLock !== null) try { fileLock.release(); } catch (ignored1) {}
            if (channel !== null) try { channel.close(); } catch (ignored2) {}
            if (randomAccessFile !== null) try { randomAccessFile.close(); } catch (ignored3) {}
        }
    }

    PluginJS.getAudioV2 = function(request, callback) {
        __jreadFiveLanePace(request);
        return __jreadFiveLaneOriginalGetAudioV2.call(PluginJS, request, callback);
    };
