function findVoice(voice) {
    var id = String(voice);
    for (var i = 0; i < ALL_VOICES.length; i++) {
        if (ALL_VOICES[i].id === id) return ALL_VOICES[i];
    }
    // 兜底：用户可能直接填了中文名
    for (var j = 0; j < ALL_VOICES.length; j++) {
        if (ALL_VOICES[j].name === id) return ALL_VOICES[j];
    }
    return null;
}

// ---------------------------------------------------------------- 请求封装

function buildHeaders(contentType) {
    return {
        "Content-Type": contentType,
        "Accept": "application/json, text/plain, */*",
        "Accept-Language": "zh",
        "X-Requested-With": "XMLHttpRequest",
        "X-Source": "h5",
        "X-AgentID": "HunyuanDefault",
        "Origin": ORIGIN,
        "Referer": ORIGIN + "/",
        "User-Agent": UA,
        "Cookie": cookie
    };
}

/**
 * POST 并解析 JSON。
 *
 * 注意：**不要用 `resp.json()`**。它在宿主侧是 `parseJsonValue()` →
 * `jsonObjectToJava()`，返回的是一个 `java.util.LinkedHashMap`。Rhino 里对 Map
 * 做属性访问拿到的是装箱的 Java 对象（`java.lang.Integer` / `String`），
 * 跟 JS 原始值做 `===` / `!==` 永远不相等 —— `j.code !== 0` 会恒为 true，
 * 于是接口明明返回 `{"code":0,"msg":"success"}` 也被判成失败。
 * （`resp.code()` 是方法返回值，Rhino 会转成 JS 数字，所以 HTTP 状态判断反而是对的。）
 *
 * 改用 `JSON.parse(resp.text())` 拿到原生 JS 对象，数字/字符串都是原始类型。
 */
function postJson(path, bodyObj) {
    var resp = ttsrv.httpPost(HOST + path, JSON.stringify(bodyObj), buildHeaders("application/json"));
    if (Number(resp.code()) !== 200) {
        throw "混元接口 HTTP " + resp.code() + ": " + resp.text().substring(0, 200);
    }
    var raw = resp.text();
    // 优先自己 parse（原生 JS 对象）；宿主没有 JSON 全局时退回 resp.json()，
    // 但那时读出来的值是 Java 装箱对象，所以下面的 code 一律过 Number() 再比。
    var j = (typeof JSON !== 'undefined' && typeof JSON.parse === 'function')
        ? JSON.parse(raw)
        : resp.json();
    if (!j || Number(j.code) !== 0) {
        throw "混元接口返回错误: " + (j && j.msg ? String(j.msg) : raw.substring(0, 200));
    }
    return j;
}

// ---------------------------------------------------------------- WAV 封装

/**
 * 给裸 PCM 补 44 字节 WAV 头。
 * 参数一律取自响应的 sampleRate / channel / bitDepth，不写死。
 */
function pcmToWav(pcm, sampleRate, channels, bits) {
    var byteRate = sampleRate * channels * bits / 8;
    var blockAlign = channels * bits / 8;
    var bb = java.nio.ByteBuffer.allocate(44 + pcm.length);
    bb.order(java.nio.ByteOrder.LITTLE_ENDIAN);
    bb.put(java.lang.String("RIFF").getBytes("UTF-8"));
    bb.putInt(36 + pcm.length);
    bb.put(java.lang.String("WAVE").getBytes("UTF-8"));
    bb.put(java.lang.String("fmt ").getBytes("UTF-8"));
    bb.putInt(16);                 // PCM 格式块大小
    bb.putShort(1);                // audioFormat = 1 (PCM)
    bb.putShort(channels);
    bb.putInt(sampleRate);
    bb.putInt(byteRate);
    bb.putShort(blockAlign);
    bb.putShort(bits);
    bb.put(java.lang.String("data").getBytes("UTF-8"));
    bb.putInt(pcm.length);
    bb.put(pcm, 0, pcm.length);
    return bb.array();
}

// ---------------------------------------------------------------- 两种合成

function synthA(text, v) {
    var j = postJson("/api/new-portal/audio/synthesis", {
        speakerId: v.id,
        prompt: text
    });
    var d = j.data || {};
    if (d.url) {
        // COS 直链 PCM：下载 → 补 WAV 头
        var pcm = ttsrv.httpGetBytes(d.url, { "User-Agent": UA });
        return pcmToWav(pcm, d.sampleRate || 24000, d.channel || 1, d.bitDepth || 16);
    }
    if (d.base64Audio) {
        // 克隆音色：base64 内嵌 MP3，解码后直接返回
        return ttsrv.base64DecodeToBytes(d.base64Audio);
    }
    throw "混元未返回音频数据（既无 url 也无 base64Audio）";
}

function synthB(text, v, rate) {
    // rate 基准 50 = 1.0 倍；方式B 支持小数语速（实测 0.5/1.5/2 均可用）
    var speed = rate / 50;
    var j = postJson("/api/vision_platform/audio/tts", {
        prompt: text,
        speed: speed,
        toneId: parseInt(v.id, 10)   // 必须是整数
    });
    var d = j.data || {};
    var url = d.voiceCosUrl || d.url;
    if (!url) throw "混元未返回 voiceCosUrl";
    return ttsrv.httpGetBytes(url, { "User-Agent": UA });
}

